content.query:
// Throttled requests (HTTP 429) over time
CDBDataPlaneRequests
| where TimeGenerated {timeRange}
| where StatusCode == 429
| summarize ThrottledCount = count() by bin(TimeGenerated, 15m), DatabaseName, CollectionName
| order by TimeGenerated asc

// Server-side errors (5xx) over time
CDBDataPlaneRequests
| where TimeGenerated {timeRange}
| where StatusCode >= 500
| summarize ErrorCount = count() by bin(TimeGenerated, 1h), StatusCode, OperationName
| order by TimeGenerated asc
